import os,sys;sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)));from _paths import media  # noqa: E402
import cv2,json,numpy as np,pathlib
b=media('reconstruction/2026-campus/modular/research');sift=cv2.SIFT_create(nfeatures=30000);data={}
for kind in ['cad','scan']:
 im=cv2.imread(str(b/f'{kind}-alignment-map.png'),0);kp,ds=sift.detectAndCompute(im,None);meta=json.load(open(b/f'{kind}-alignment-map.json'));xy=np.array([k.pt for k in kp]);world=np.column_stack([(xy[:,0]/meta['resolution']-.5)*meta['scale']+meta['center'][0],(.5-xy[:,1]/meta['resolution'])*meta['scale']+meta['center'][1]]);data[kind]=(kp,ds,world);print(kind,len(kp),flush=True)
matches=cv2.FlannBasedMatcher(dict(algorithm=1,trees=5),dict(checks=100)).knnMatch(data['scan'][1],data['cad'][1],k=2);good=[a for a,c in matches if a.distance<.7*c.distance];x=np.array([data['scan'][2][m.queryIdx] for m in good]);y=np.array([data['cad'][2][m.trainIdx] for m in good]);M,mask=cv2.estimateAffinePartial2D(x,y,method=cv2.RANSAC,ransacReprojThreshold=1.2,maxIters=20000,confidence=.999);err=np.linalg.norm(x@M[:,:2].T+M[:,2]-y,axis=1);ok=mask.ravel()>0;res={'scan_xy_to_cad_xy':M.tolist(),'matches':len(good),'inliers':int(ok.sum()),'rms_m':float(np.sqrt(np.mean(err[ok]**2))),'median_m':float(np.median(err[ok])),'scale':float(np.linalg.norm(M[:,0])),'rotation_deg':float(np.degrees(np.arctan2(M[1,0],M[0,0])))};(b/'scan-to-cad-map.json').write_text(json.dumps(res,indent=2));np.savez(b/'map-matches.npz',scan=x,cad=y,inliers=ok);print(res,flush=True)
